class RandomizedSet {
  // Значения подряд в массиве — по нему выбираем случайный элемент за O(1)
  private values: number[] = [];
  // Значение -> его индекс в массиве values
  private indexOf = new Map<number, number>();

  constructor() {}

  insert(val: number): boolean {
    // Уже есть — ничего не делаем
    if (this.indexOf.has(val)) return false;

    // Дописываем в конец массива и запоминаем индекс
    this.indexOf.set(val, this.values.length);
    this.values.push(val);
    return true;
  }

  remove(val: number): boolean {
    const idx = this.indexOf.get(val);
    if (idx === undefined) return false;

    // Удалять из середины массива дорого (O(n)), поэтому
    // переносим последний элемент на место удаляемого
    const last = this.values[this.values.length - 1];
    this.values[idx] = last;
    this.indexOf.set(last, idx);

    // Теперь удаляемое значение «лишнее» только в конце — убираем за O(1)
    this.values.pop();
    this.indexOf.delete(val);
    return true;
  }

  getRandom(): number {
    // Равновероятный индекс в [0, length)
    const i = Math.floor(Math.random() * this.values.length);
    return this.values[i];
  }
}

// Время: O(1) в среднем на каждую операцию
// Память: O(n) — массив и хеш-таблица
